        'm': 'cm',
        'cm': 'm',
        'kg': 'g',
        'g': 'kg',
        'C': 'F',
        'F': 'C'
    }

    if from_unit not in conversion_map:
        raise ValueError(f"Unsupported from unit: {from_unit}")
    if to_unit not in conversion_map:
        raise ValueError(f"Unsupported to unit: {to_unit}")

    from_unit = conversion_map[from_unit]
    to_unit = conversion_map[to_unit]

    if from_unit == to_unit:
        return value

    factor = 100 if (from_unit == 'm' and to_unit == 'cm') or (from_unit == 'cm' and to_unit == 'm') \
             else 1000 if (from_unit == 'kg' and to_unit == 'g') or (from_unit == 'g' and to_unit == 'kg') \
             else None

    if factor is None:
        raise ValueError(f"Unsupported conversion: {from_unit} to {to_unit}")

    if from_unit == 'm' and to_unit == 'cm':
        return value * factor
    elif from_unit == 'cm' and to_unit == 'm':
