def process_queries(N, queries):
    from collections import defaultdict

    # Initialize parent array for DSU (Disjoint Set Union)
    parent = list(range(N + 1))
    rank = [0] * (N + 1)

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        # Union by rank
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    results = []

    for op in queries:
        if op.startswith("connect"):
            x, y = map(int, op.split())
            union(x, y)
        elif op.startswith("is_connected"):
            x, y = map(int, op.split())
            results.append(find(x) == find(y))

    return results
