def is_monotonic(x):
    # If the list has fewer than 2 elements, it cannot be strictly monotonic.
    if len(x) < 2:
        return False

    # Determine the direction of monotonicity by comparing the first two elements.
    first, second = x[0], x[1]
    is_inc = first < second
    is_dec = first > second

    # If the list has only one element, it is trivially monotonic (but our check above
    # ensures len(x) >= 2, so this case won't occur).
    if len(x) == 2:
        return is_inc or is_dec

    # Now we need to verify that the chosen direction holds for all consecutive pairs.
    # We will use a recursive approach to avoid explicit loops.
    def check_direction(n, current, prev):
        if n == 0:
            return True
        next_val = x[n]
        if is_inc:
            return next_val > prev
        else:
            return next_val < prev

    # Start the recursion from index 1 with the first two elements.
    return check_direction(len(x) - 1, second, first)
