            stack.append(val)
        except ValueError:
            if not token.startswith("'") and not token.startswith('"'):
                # Try to interpret as variable name
                var_name = token
                if var_name in variables:
                    val = variables[var_name]
                    stack.append(val)
                else:
                    raise ValueError(error_msg)
            else:
                raise ValueError(error_msg)

        elif token == "+":
            b = stack.pop()
            a = stack.pop()
            stack.append(a + b)
        elif token == "-":
            b = stack.pop()
            a = stack.pop()
            stack.append(a - b)
        elif token == "*":
            b = stack.pop()
            a = stack.pop()
            stack.append(a * b)
        elif token == "/":
            b = stack.pop()
            a = stack.pop()
            if b == 0:
                raise ValueError(error_msg)
            stack.append(a / b)
        elif token == "%":
